test('greenEnergy sets Fuel Type', () => {
  const mod = require('./index.js');
  expect(typeof mod.greenEnergy).toBe('function');
  const obj = { 'Fuel Type': 'diesel' };
  mod.greenEnergy(obj);
  expect(obj['Fuel Type']).toBe('avocado oil');
});

test('remotelyDisable sets disabled', () => {
  const mod = require('./index.js');
  expect(typeof mod.remotelyDisable).toBe('function');
  const obj = { disabled: false };
  mod.remotelyDisable(obj);
  expect(obj.disabled).toBe(true);
});
